    section: "B", questionRef: "2022 HL Q16(a)(i)",
    questionText: "What are the likely impacts of rent caps on social sustainability?",
    tariffModel: {"kind":"bestNofParts","notation":"1 @ 8","answer":1,"ofParts":5,"perPart":8}, totalMarks: 8,
