    id: "econ-2023-hl-sa-q5-b", topicId: "economics-0-1", conceptId: "efficient-inefficient-and-impossible-points",
    section: "A", questionRef: "2023 HL Section A Q5(b)",
    questionText: "A production possibilities frontier shows an efficient, an inefficient and an impossible production point. Justify each of your choices.",
    tariffModel: {"kind":"bestNofParts","notation":"3 @ 2","answer":3,"ofParts":3,"perPart":2}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "anyN", verbatim: "A production point justified — all three", marks: 6, contextNote: "Three justifications, 2 marks each. The three are the whole answer, not a choice.", openList: true, group: {"claimMax":3,"perOption":2,"options":["Efficient refers to a production point where the firm is making the best possible use of scarce resources. i.e. it is producing as much as it can given their current resources. This can be seen anywhere on the boundary – Point C.","Inefficient refers to a production point where the firm is wasteful of scarce resources. i.e. it is possible to produce more tablets and laptops given their current resources. This can be seen anywhere inside the boundary – Point A","Impossible refers to a production point which the firm cannot currently produce given their current scarce resources. In order to produce this level of output they need to increase their factors of production. This can be seen anywhere outside the boundary – Point B."]} },
    ],
